module cake_divider #(\n    parameter N = 8,\n    parameter M = 4\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire signed [15:0] x_candles [0:N-1],\n    input wire signed [15:0] y_candles [0:N-1],\n    input wire signed [31:0] a_lines [0:M-1],\n    input wire signed [31:0] b_lines [0:M-1],\n    input wire signed [31:0] c_lines [0:M-1],\n    input wire [7:0] n,\n    input wire [7:0] m,\n    input wire signed [15:0] r,\n    output reg done,\n    output reg result\n);\n\n    // State definitions\n    localparam [4:0] IDLE = 5'd0;\n    localparam [4:0] INIT_PAIR = 5'd1;\n    localparam [4:0] COMPUTE_DET = 5'd2;\n    localparam [4:0] CHECK_DET = 5'd3;\n    localparam [4:0] COMPUTE_DXDY = 5'd4;\n    localparam [4:0] SQUARE = 5'd5;\n    localparam [4:0] COMPARE = 5'd6;\n    localparam [4:0] NEXT_PAIR = 5'd7;\n    localparam [4:0] CHECK_F = 5'd8;\n    localparam [4:0] COMPARE_F = 5'd9;\n    localparam [4:0] INIT_SIG = 5'd10;\n    localparam [4:0] COMPUTE_SIG = 5'd11;\n    localparam [4:0] NEXT_CANDLE = 5'd12;\n    localparam [4:0] CHECK_DUP = 5'd13;\n    localparam [4:0] DONE = 5'd14;\n\n    reg [4:0] state;\n    reg [3:0] i, j;\n    reg [3:0] k;\n    reg [3:0] l;\n    reg signed [63:0] det;\n    reg signed [63:0] dx, dy;\n    reg signed [63:0] lhs, rhs;\n    reg [3:0] I;\n    reg [7:0] F;\n    reg [M-1:0] signatures [0:N-1];\n    reg [M-1:0] current_sig;\n    reg duplicate_found;\n    reg signed [31:0] a_i, b_i, c_i;\n    reg signed [31:0] a_j, b_j, c_j;\n\n    wire signed [63:0] val_current;\n    assign val_current = $signed(a_lines[l]) * $signed(x_candles[k]) + $signed(b_lines[l]) * $signed(y_candles[k]) + $signed(c_lines[l]);\n\n    integer idx_i, idx_j, idx;\n    reg duplicate_found_wire;\n\n    always @(*) begin\n        duplicate_found_wire = 1'b0;\n        for (idx_i = 0; idx_i < N; idx_i = idx_i + 1) begin\n            for (idx_j = idx_i + 1; idx_j < N; idx_j = idx_j + 1) begin\n                if (idx_i < n && idx_j < n && signatures[idx_i] == signatures[idx_j]) begin\n                    duplicate_found_wire = 1'b1;\n                end\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            I <= 4'd0;\n            F <= 8'd0;\n            i <= 4'd0;\n            j <= 4'd1;\n            k <= 4'd0;\n            l <= 4'd0;\n            duplicate_found <= 1'b0;\n            for (idx = 0; idx < N; idx = idx + 1) begin\n                signatures[idx] <= {M{1'b0}};\n            end\n            current_sig <= {M{1'b0}};\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT_PAIR;\n                        I <= 4'd0;\n                        i <= 4'd0;\n                        j <= 4'd1;\n                    end\n                end\n                INIT_PAIR: begin\n                    a_i <= a_lines[i];\n                    b_i <= b_lines[i];\n                    c_i <= c_lines[i];\n                    a_j <= a_lines[j];\n                    b_j <= b_lines[j];\n                    c_j <= c_lines[j];\n                    state <= COMPUTE_DET;\n                end\n                COMPUTE_DET: begin\n                    det <= a_i * b_j - a_j * b_i;\n                    state <= CHECK_DET;\n                end\n                CHECK_DET: begin\n                    if (det == 64'd0) begin\n                        state <= NEXT_PAIR;\n                    end else begin\n                        state <= COMPUTE_DXDY;\n                    end\n                end\n                COMPUTE_DXDY: begin\n                    dx <= b_i * c_j - b_j * c_i;\n                    dy <= c_i * a_j - c_j * a_i;\n                    state <= SQUARE;\n                end\n                SQUARE: begin\n                    lhs <= dx * dx + dy * dy;\n                    rhs <= (r * r) * (det * det);\n                    state <= COMPARE;\n                end\n                COMPARE: begin\n                    if (lhs < rhs) begin\n                        I <= I + 4'd1;\n                    end\n                    state <= NEXT_PAIR;\n                end\n                NEXT_PAIR: begin\n                    if (j < m - 1) begin\n                        j <= j + 4'd1;\n                        state <= INIT_PAIR;\n                    end else begin\n                        j <= i + 4'd2;\n                        if (i < m - 2) begin\n                            i <= i + 4'd1;\n                            state <= INIT_PAIR;\n                        end else begin\n                            state <= CHECK_F;\n                        end\n                    end\n                end\n                CHECK_F: begin\n                    F <= 8'd1 + m + I;\n                    state <= COMPARE_F;\n                end\n                COMPARE_F: begin\n                    if (F != n) begin\n                        result <= 1'b0;\n                        state <= DONE;\n                    end else begin\n                        k <= 4'd0;\n                        state <= INIT_SIG;\n                    end\n                end\n                INIT_SIG: begin\n                    current_sig <= {M{1'b0}};\n                    l <= 4'd0;\n                    state <= COMPUTE_SIG;\n                end\n                COMPUTE_SIG: begin\n                    if (val_current > 63'd0) begin\n                        current_sig[l] <= 1'b1;\n                    end else begin\n                        current_sig[l] <= 1'b0;\n                    end\n                    if (l < m - 1) begin\n                        l <= l + 4'd1;\n                        state <= COMPUTE_SIG;\n                    end else begin\n                        state <= NEXT_CANDLE;\n                    end\n                end\n                NEXT_CANDLE: begin\n                    signatures[k] <= current_sig;\n                    k <= k + 4'd1;\n                    if (k < n - 1) begin\n                        state <= INIT_SIG;\n                    end else begin\n                        state <= CHECK_DUP;\n                    end\n                end\n                CHECK_DUP: begin\n                    duplicate_found <= duplicate_found_wire;\n                    state <= DONE;\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    if (duplicate_found) begin\n                        result <= 1'b0;\n                    end else begin\n                        result <= 1'b1;\n                    end\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule